		return nil, storeError(ErrData, str, nil)
	}
	txOut := rec.MsgTx.TxOut[outpoint.Index]

	blockTime, err := fetchBlockTime(ns, block.Height)
	if err != nil {
		return nil, err
	}

	credit := &Credit{
		OutPoint: outpoint,
		BlockMeta: BlockMeta{
			Block: block,
			Time:  blockTime,
		},
		Amount:       btcutil.Amount(txOut.Value),
		PkScript:     txOut.PkScript,
